{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Tocotrienol, a polyprenylated chromanol structurally related to the query's prenylated oxygenated ring, has poor oral bioavailability in humans, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Direct human systemic-availability measurements for lycopene, a long-chain polyisoprenoid, show only 0.17% of an oral dose reaches the circulation, supporting low F for the similarly highly lipophilic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Phytoene, a C40 carotenoid with a polyisoprenoid chain, was estimated to have 58.5% bioavailability in humans by compartmental modeling, which would support high F but is less transferable to the quinone-containing query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "An isotope study estimated 23.2% bioavailability for all-trans lycopene in humans, above the 20% threshold, but this is a compartmental-model estimate and less transferable to the query's polyprenyl quinone structure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a high-molecular-weight polyprenyl benzoquinone. The most transferable experimental evidence—tocotrienol poor oral bioavailability and direct lycopene systemic-availability measurements—indicates F below 20%. Contradictory high estimates come from carotenoid compartmental-modeling studies that are less structurally transferable. Overall, the weight of evidence supports low oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability data exist for a polyprenyl benzoquinone/ubiquinone analogue in humans.",
    "The tocotrienol record is qualitative ('poor') and lacks a numeric F value for threshold comparison.",
    "Carotenoid evidence is mixed between low systemic-availability measurements and higher compartmental-model estimates, creating uncertainty in extrapolation."
  ],
  "new_evidence_assessment": [
    {
